{
    string htmlASCIIHexEncoded = string.Empty; ;
    foreach (char c in str)
    {
        try
        {
            int val = Convert.ToInt32(c);
            if (val < 128) ## if ASCCI not extended
            {
                htmlASCIIHexEncoded += "&#x" + val.ToString("X") + ";";
