            socket.send(JSON.stringify({ error: error.toString() }));
          }
        });

        socket.addEventListener("close", (event) => {
          console.log('WebSocket connection lost. Retrying in 5 seconds...');
          setTimeout(connectWebSocket, 5000);
        });
      }

